import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let {alpha} real numbers d_1, d_2, ..., d_{alpha} lie in the closed interval [{l}, {u}]. They satisfy the constraint sum over i=1 to {alpha} of ({a3}*d_i^3 + {a2}*d_i^2 + {a1}*d_i + {a0}) equals {k}. Determine the maximum possible value of S = d_1 + d_2 + ... + d_{alpha}. Your final numeric answer should be exact.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose number of variables
alpha = rng.randint(24, 60)
# Choose interval endpoints L < U
l = rng.randint(1, 5)
u = rng.randint(l+1, l+6)
# Choose parameters to build a tailored cubic that admits a sharp linear lower bound on [l, u]
t = rng.randint(1, 4)  # positive leading coefficient ensures proper behavior
A = rng.randint(2, 9)  # positive slope of the supporting line
B = rng.randint(-15, 15)
# Construct cubic coefficients via p(d) = A*d + B + t*(d - l)*(d - u)**2
a3 = t
a2 = -t*(2*u + l)
a1 = A + t*(u*u + 2*l*u)
a0 = B - t*l*u*u
# Ensure a nontrivial mixture count r so K forces some d_i at U and the rest at L for extremality
r = rng.randint(1, alpha-1)
# Compute K so that K = alpha*p(L) + r*(p(U) - p(L)), and note p(U) - p(L) = A*(u - l)
pL = a3*l**3 + a2*l**2 + a1*l + a0  # should equal A*l + B
K = alpha*pL + r*A*(u - l)
# Return assignment dict
return {
    'alpha': alpha,
    'l': l,
    'u': u,
    'a3': a3,
    'a2': a2,
    'a1': a1,
    'a0': a0,
    'k': K
}

    def verifier(assign):
# Validate presence of keys
required = ['alpha', 'l', 'u', 'a3', 'a2', 'a1', 'a0', 'k']
for key in required:
    if key not in assign:
        # Missing parameter
        return (False, None)
alpha = assign['alpha']
l = assign['l']
u = assign['u']
a3 = assign['a3']
a2 = assign['a2']
a1 = assign['a1']
a0 = assign['a0']
K = assign['k']
# Basic domain checks
if not (isinstance(alpha, int) and isinstance(l, int) and isinstance(u, int) and isinstance(a3, int) and isinstance(a2, int) and isinstance(a1, int) and isinstance(a0, int) and isinstance(K, int)):
    return (False, None)
if alpha < 2 or l >= u:
    return (False, None)
# Recover A and B from the constructed cubic identity p(d) = A*d + B + a3*(d - l)*(d - u)^2
# From coefficient comparison: a2 must equal -a3*(2u + l)
if a2 != -a3*(2*u + l):
    # Not our intended family
    return (False, None)
# Infer A and B
A = a1 - a3*(u*u + 2*l*u)
B = a0 + a3*l*u*u
# Must have a3>0 and A>0 to ensure the supporting line is meaningful
if not (A > 0 and a3 > 0):
    return (False, None)
# Check that p(L) = A*L + B holds for consistency
pL_direct = a3*l**3 + a2*l**2 + a1*l + a0
if pL_direct != A*l + B:
    return (False, None)
# Compute r implied by K: K = alpha*p(L) + r*(p(U) - p(L)) and p(U) - p(L) = A*(u - l)
pU_minus_pL = A*(u - l)
if pU_minus_pL <= 0:
    return (False, None)
numer = K - alpha*(A*l + B)
if numer % pU_minus_pL != 0:
    # r is not integer, invalid instance
    return (False, None)
r = numer // pU_minus_pL
# Enforce nontrivial mixture for difficulty
if not (1 <= r <= alpha - 1):
    return (False, None)
# The maximum sum is achieved when all d_i are at endpoints with exactly r at U and alpha - r at L
S_max = alpha*l + r*(u - l)
# Cross-check with the linear bound S_max = (K - alpha*B)/A when the slack terms vanish
check_val = (K - alpha*B) / A
# Must be integer and equal to S_max
if abs(check_val - S_max) > 1e-9:
    return (False, None)
return (True, S_max)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

